ExprDef *append_keysym_list(ExprDef *expr, ExprDef *append) {
    size_t original_size = expr->keysym_count;
    size_t append_size = append->keysym_count;

    // Resize keysym and keysym_map arrays in expr to accommodate the appended data
    expr->keysym = realloc(expr->keysym, (original_size + append_size) * sizeof(*expr->keysym));
    expr->keysym_map = realloc(expr->keysym_map, (original_size + append_size) * sizeof(*expr->keysym_map));

    // Copy keysym and keysym_map data from append to expr
    for (size_t i = 0; i < append_size; ++i) {
        expr->keysym[original_size + i] = append->keysym[i];
        expr->keysym_map[original_size + i] = append->keysym_map[i];
    }

    // Update the count of keysym entries in expr
    expr->keysym_count += append_size;

    // Free the memory associated with append
    free(append->keysym);
    free(append->keysym_map);
    free(append);

    return expr;
}

